-- 0001 — Tablas del dataset sintético 0.4.0 y data_loads (U2; DT-044, docs/04 §9).
--
-- Una tabla por archivo del dataset, con las columnas del contrato en su nombre y su orden
-- (DT-024, DT-034, DT-038, DT-039). Los id del dataset son las claves primarias; las columnas
-- de identidad son GENERATED BY DEFAULT para admitirlos, y la ingesta ajusta las secuencias.
-- Cantidades en numeric sin precisión fija (DT-044). Vocabularios cerrados con CHECK según el
-- modelo (docs/04 §3), no solo lo que emite 0.4.0. Referencias polimórficas sin FK (§9.3).

CREATE TABLE locations (
    id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code        text    NOT NULL UNIQUE,
    name        text    NOT NULL,
    type        text    NOT NULL,
    is_active   boolean NOT NULL,
    data_origin text    NOT NULL CHECK (data_origin IN ('SYNTHETIC', 'REAL'))
);

CREATE TABLE categories (
    id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code        text    NOT NULL UNIQUE,
    name        text    NOT NULL,
    parent_id   bigint,
    is_active   boolean NOT NULL,
    data_origin text    NOT NULL CHECK (data_origin IN ('SYNTHETIC', 'REAL'))
);

CREATE TABLE suppliers (
    id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code         text        NOT NULL UNIQUE,
    name         text        NOT NULL,
    contact_info text,
    is_active    boolean     NOT NULL,
    currency     text,
    created_at   timestamptz NOT NULL,
    updated_at   timestamptz NOT NULL,
    data_origin  text        NOT NULL CHECK (data_origin IN ('SYNTHETIC', 'REAL'))
);

CREATE TABLE products (
    id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sku             text        NOT NULL UNIQUE,
    name            text        NOT NULL,
    description     text,
    category_id     bigint      NOT NULL REFERENCES categories (id),
    unit_of_measure text        NOT NULL,
    is_active       boolean     NOT NULL,
    abc_class       text,
    rotation_class  text,
    shelf_life_days integer,
    valid_from      date        NOT NULL,
    valid_to        date,
    created_at      timestamptz NOT NULL,
    updated_at      timestamptz NOT NULL,
    data_origin     text        NOT NULL CHECK (data_origin IN ('SYNTHETIC', 'REAL')),
    CONSTRAINT products_validity_ck CHECK (valid_to IS NULL OR valid_from <= valid_to)
);

CREATE TABLE product_suppliers (
    id                    bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    product_id            bigint  NOT NULL REFERENCES products (id),
    supplier_id           bigint  NOT NULL REFERENCES suppliers (id),
    agreed_lead_time_days integer NOT NULL,
    moq                   numeric NOT NULL CHECK (moq >= 0),
    order_multiple        numeric NOT NULL CHECK (order_multiple >= 1),
    unit_cost             numeric NOT NULL,
    is_preferred          boolean NOT NULL,
    is_active             boolean NOT NULL,
    data_origin           text    NOT NULL CHECK (data_origin IN ('SYNTHETIC', 'REAL')),
    CONSTRAINT product_suppliers_pair_uk UNIQUE (product_id, supplier_id)
);

-- Como máximo un proveedor preferente activo por producto (docs/04 §3.4).
CREATE UNIQUE INDEX product_suppliers_one_active_preferred_ux
    ON product_suppliers (product_id)
    WHERE is_preferred AND is_active;

CREATE TABLE purchase_orders (
    id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_number text        NOT NULL UNIQUE,
    supplier_id  bigint      NOT NULL REFERENCES suppliers (id),
    location_id  bigint      NOT NULL REFERENCES locations (id),
    status       text        NOT NULL
        CHECK (status IN ('DRAFT', 'ISSUED', 'PARTIALLY_RECEIVED', 'RECEIVED', 'CANCELLED')),
    issued_at    timestamptz NOT NULL,
    expected_at  timestamptz NOT NULL,
    closed_at    timestamptz,
    currency     text,
    total_amount numeric,
    created_by   text,
    created_at   timestamptz NOT NULL,
    updated_at   timestamptz NOT NULL,
    data_origin  text        NOT NULL CHECK (data_origin IN ('SYNTHETIC', 'REAL'))
);

CREATE TABLE purchase_order_items (
    id                bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    purchase_order_id bigint      NOT NULL REFERENCES purchase_orders (id),
    product_id        bigint      NOT NULL REFERENCES products (id),
    quantity_ordered  numeric     NOT NULL CHECK (quantity_ordered > 0),
    quantity_received numeric     NOT NULL,
    unit_cost         numeric     NOT NULL,
    expected_at       timestamptz,
    data_origin       text        NOT NULL CHECK (data_origin IN ('SYNTHETIC', 'REAL')),
    CONSTRAINT purchase_order_items_order_product_uk UNIQUE (purchase_order_id, product_id),
    CONSTRAINT purchase_order_items_received_ck
        CHECK (quantity_received >= 0 AND quantity_received <= quantity_ordered)
);

CREATE TABLE purchase_order_receipts (
    id                     bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    purchase_order_item_id bigint      NOT NULL REFERENCES purchase_order_items (id),
    received_at            timestamptz NOT NULL,
    quantity_received      numeric     NOT NULL,
    quality_rejected       numeric,
    data_origin            text        NOT NULL CHECK (data_origin IN ('SYNTHETIC', 'REAL')),
    CONSTRAINT purchase_order_receipts_item_received_uk UNIQUE (purchase_order_item_id, received_at)
);

-- Demanda latente: solo existe en datos sintéticos (docs/04 §3.7-bis).
CREATE TABLE demand (
    id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    product_id  bigint  NOT NULL REFERENCES products (id),
    location_id bigint  NOT NULL REFERENCES locations (id),
    occurred_on date    NOT NULL,
    quantity    numeric NOT NULL,
    data_origin text    NOT NULL CHECK (data_origin = 'SYNTHETIC'),
    CONSTRAINT demand_day_uk UNIQUE (product_id, location_id, occurred_on)
);

-- Demanda satisfecha (docs/04 §3.8).
CREATE TABLE consumption (
    id                   bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    product_id           bigint  NOT NULL REFERENCES products (id),
    location_id          bigint  NOT NULL REFERENCES locations (id),
    occurred_on          date    NOT NULL,
    quantity             numeric NOT NULL,
    channel              text,
    is_stockout_affected boolean NOT NULL,
    data_origin          text    NOT NULL CHECK (data_origin IN ('SYNTHETIC', 'REAL')),
    CONSTRAINT consumption_day_uk UNIQUE (product_id, location_id, occurred_on)
);

CREATE TABLE inventory_movements (
    id             bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    product_id     bigint      NOT NULL REFERENCES products (id),
    location_id    bigint      NOT NULL REFERENCES locations (id),
    movement_type  text        NOT NULL CHECK (movement_type IN (
        'RECEIPT', 'ISSUE', 'ADJUSTMENT', 'RETURN', 'TRANSFER_IN', 'TRANSFER_OUT', 'SCRAP')),
    quantity       numeric     NOT NULL CHECK (quantity <> 0),
    occurred_at    timestamptz NOT NULL,
    recorded_at    timestamptz NOT NULL,
    reference_type text        NOT NULL,
    reference_id   bigint,
    reason_code    text,
    data_origin    text        NOT NULL CHECK (data_origin IN ('SYNTHETIC', 'REAL')),
    created_by     text,
    -- Orden total de DT-038 §5.4: el tipo sustituye a su rango; reference_id nulo cuenta como valor.
    CONSTRAINT inventory_movements_business_uk UNIQUE NULLS NOT DISTINCT
        (product_id, location_id, occurred_at, movement_type, reference_id)
);

-- Snapshot al corte, no una serie (docs/04 §3.6).
CREATE TABLE inventory (
    id                  bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    product_id          bigint      NOT NULL REFERENCES products (id),
    location_id         bigint      NOT NULL REFERENCES locations (id),
    quantity_on_hand    numeric     NOT NULL CHECK (quantity_on_hand >= 0),
    quantity_reserved   numeric     NOT NULL,
    quantity_in_transit numeric     NOT NULL,
    last_movement_at    timestamptz,
    updated_at          timestamptz NOT NULL,
    data_origin         text        NOT NULL CHECK (data_origin IN ('SYNTHETIC', 'REAL')),
    CONSTRAINT inventory_pair_uk UNIQUE (product_id, location_id)
);

-- Un intento de carga por fila; el manifiesto íntegro (docs/04 §9.4). ALREADY_LOADED no escribe nada.
CREATE TABLE data_loads (
    id                bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    dataset_version   text        NOT NULL,
    generator_version text,
    data_origin       text CHECK (data_origin IN ('SYNTHETIC', 'REAL')),
    time_range        daterange,
    manifest          jsonb       NOT NULL,
    manifest_sha256   text        NOT NULL,
    files             jsonb       NOT NULL,
    status            text        NOT NULL CHECK (status IN ('COMPLETED', 'FAILED')),
    outcome           text        NOT NULL,
    errors            jsonb       NOT NULL DEFAULT '[]'::jsonb,
    started_at        timestamptz NOT NULL,
    finished_at       timestamptz NOT NULL,
    CONSTRAINT data_loads_completed_has_no_errors_ck
        CHECK (status <> 'COMPLETED' OR outcome = 'COMPLETED')
);

-- Como máximo una carga COMPLETED por base: un solo linaje (DT-044).
CREATE UNIQUE INDEX data_loads_single_completed_ux ON data_loads ((status)) WHERE status = 'COMPLETED';
